    EVT_IR_Log("match reserved: waiting for the engine to start it")
    evt_ir_busy = true
    for _ = 1, EVT_IR.LAUNCH_FRAMES do
      coroutine.yield()
    end
    evt_ir_busy = false
    EVT_IR_Call(EVT_IR.LAUNCH, 2)
