  l1 = nil
end
-- ===== EVT inarogue title press END =====

-- ===== EVT inarogue BEGIN =====
-- EVT INAROGUE: in slot 4 (the INAROGUE save) the title's mode list is never shown, not even for one frame
do
  local evt_ir_open_layer = OnOpenLayer
  function OnOpenLayer(a1, a2)
    local r = table.pack(evt_ir_open_layer(a1, a2))
    if EVT_IR_InRogueSlot() and not EVT_IR_InSession() then
      EVT_IR_HideLayer(a1)
    end
    return table.unpack(r, 1, r.n)
  end
  for _, name in ipairs({"OpenVroadNoticeWindow", "OpenTournamentDeliveryUpdate", "UpdateTitleMenuFirstOpen",
                         "CheckInviteReceive"}) do
    EVT_IR_BlockInRogueSlot(name)
  end
end
-- ===== EVT inarogue END =====
